func fieldNamed(m Model, label string) (field, bool) {
	for _, s := range m.sections {
		for _, f := range s.Fields {
			if f.Label == label {
				return f, true
			}
		}
	}
	return field{}, false
}

// focusOn puts the cursor on the named field, with bindInput run so the
// on-focus value is recorded.
func focusOn(t *testing.T, m Model, label string) Model {
	t.Helper()
	for tab := range m.sections {
		for i, f := range m.sections[tab].Fields {
			if f.Label != label {
				continue
			}
			m.activeTab = tab
			m.focused = i
			m.bindInput()
			return m
		}
	}
	t.Fatalf("no %q field in the configuration view", label)
	return m
